from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
root=Path('documents')
out=Path('docx_text_index.txt')
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with out.open('w',encoding='utf-8') as f:
    for p in sorted(root.rglob('*.docx')):
        try:
            with ZipFile(p) as z:
                xml=z.read('word/document.xml')
            tree=ET.fromstring(xml)
            texts=[]
            for para in tree.findall('.//w:p',ns):
                s=''.join((t.text or '') for t in para.findall('.//w:t',ns))
                if s: texts.append(s)
            f.write('\n### FILE: '+str(p)+'\n')
            f.write('\n'.join(texts)+'\n')
        except Exception as e:
            f.write(f'\n### FILE: {p} ERROR {e}\n')
print(out, out.stat().st_size)
PY","description":"Build searchable text index of Word files","timeoutMs":120000}

