from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
import re
root=Path('documents')
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
def text(p):
    try:
      with ZipFile(p) as z: xml=z.read('word/document.xml')
      tree=ET.fromstring(xml)
      return '\n'.join(''.join((t.text or '') for t in para.findall('.//w:t',ns)) for para in tree.findall('.//w:p',ns))
    except: return ''
terms=['Funds & Asset Management','LPAC','Limited Partner Advisory Committee','advisory committee','LPA','signed','executed','never signed','not signed','not executed','unexecuted','unsigned']
out=Path('relevant_doc_summary.txt')
with out.open('w',encoding='utf-8') as f:
 for p in sorted(root.rglob('*.docx')):
  s=text(p)
  if 'Funds & Asset Management' in s or re.search(r'\bLPAC\b|Limited Partner Advisory Committee|advisory committee',s,re.I):
   hits=[t for t in terms if re.search(re.escape(t),s,re.I)]
   f.write(f'\n### {p}\nHITS: {", ".join(hits)}\n')
   # first lines/paragraphs containing strong indicators, max 20
   lines=[x.strip() for x in s.splitlines() if x.strip()]
   seen=0
   for ln in lines:
    if re.search(r'Funds & Asset Management|LPAC|Limited Partner Advisory Committee|advisory committee|never signed|not signed|not executed|unexecuted|unsigned|LPA',ln,re.I):
     f.write(ln[:1000]+'\n'); seen+=1
     if seen>=20: break
print(out.stat().st_size)
PY","description":"Summarize fund-practice and LPAC evidence","timeoutMs":120000}

