from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
import re,collections
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
def text(p):
 try:
  with ZipFile(p) as z: x=z.read('word/document.xml')
  t=ET.fromstring(x)
  return '\n'.join(''.join((u.text or '') for u in para.findall('.//w:t',ns)) for para in t.findall('.//w:p',ns))
 except: return ''
by=collections.defaultdict(list)
for p in Path('documents').rglob('*.docx'):
 s=text(p)
 if 'Funds & Asset Management' in s:
  # only docs likely administrative/engagement/intake or substantial mention
  if re.search(r'engagement|matter[- ]opening|staffing|new[- ]matter|conflict|intake|description of matter',p.name+' '+str(p),re.I):
   by[p.parts[2]].append((str(p),s))
for m in sorted(by):
 print('\n###',m)
 for p,s in by[m]:
  print('FILE',p)
  lines=[x.strip() for x in s.splitlines() if x.strip()]
  for i,l in enumerate(lines):
   if 'Funds & Asset Management' in l:
    print(' ',l[:700]);
    if i+1<len(lines): print('   ',lines[i+1][:500])
    break
PY","description":"Identify explicit funds-practice matters","timeoutMs":120000}

